/* Œconomia — Entraînement : thème « Emploi et chômage » (24 exercices, trois niveaux). */
(function () {
  const X = OEC.exo, { rnd, pick, fmt } = X;
  const P = (...a) => a.map((t) => `<p>${t}</p>`).join("");

  X.theme({ id: "emploi", nom: "Emploi et chômage",
    intro: "Comment mesure-t-on le chômage, pourquoi existe-t-il même quand l’économie va bien, et que peuvent faire les politiques publiques ? Ces exercices vous entraînent à calculer des taux, à raisonner sur les flux du marché du travail et à confronter les grandes explications du chômage.",
    notions: ["taux-naturel", "hysterese", "demande-effective", "courbe-phillips", "concurrence-imparfaite", "destruction-creatrice"] });

  X.add([
  /* =========================== NIVEAU 1 : DÉCOUVERTE =========================== */
  { id: "em1-bit", theme: "emploi", niveau: 1, type: "qcm", notion: "taux-naturel",
    titre: "Qui est chômeur ?", competence: "Appliquer la définition du chômage du Bureau international du travail.",
    enonce: P("Selon la définition du Bureau international du travail (BIT), laquelle de ces personnes est au chômage ?"),
    options: ["Lucie, 20 ans, étudiante à plein temps, qui ne cherche pas d’emploi.", "Paul, 66 ans, retraité.", "Sara, 34 ans, licenciée il y a deux mois, qui envoie des candidatures et pourrait commencer dès demain.", "Marc, 45 ans, qui travaille à 50 % et voudrait travailler davantage."], c: 2, pourquoi: ["Lucie ne cherche pas d’emploi : elle est inactive, pas au chômage.", "Paul est retraité et ne cherche pas d’emploi : il est inactif.", null, "Marc a un emploi : il est en sous-emploi, mesuré à part, pas au chômage."],
    explication: P("Pour le BIT, est chômeur celui qui, à la fois, <b>n’a pas d’emploi</b>, <b>cherche activement</b> un emploi et est <b>disponible</b> pour travailler rapidement. C’est le cas de Sara.", "Lucie et Paul sont <b>inactifs</b> : ils ne cherchent pas d’emploi. Marc a un emploi : il est en <b>sous-emploi</b>, une situation que les statistiques mesurent à part.") },

  { id: "em1-taux", theme: "emploi", niveau: 1, type: "calcul", notion: "taux-naturel",
    titre: "Calculer un taux de chômage", competence: "Calculer le taux de chômage à partir de la population active.",
    gen: () => ({ occ: rnd(180, 260) * 1000, ch: rnd(4, 12) * 1000 }),
    enonce: (p) => P(`Dans une région, <b>${fmt(p.occ)}</b> personnes ont un emploi et <b>${fmt(p.ch)}</b> sont au chômage.`, "Calculez la population active, puis le taux de chômage (arrondi à une décimale)."),
    champs: [{ label: "Population active", unite: "personnes", tol: 0.5 }, { label: "Taux de chômage", unite: "%", tol: 0.1 }],
    reponses: (p) => [p.occ + p.ch, Math.round((p.ch / (p.occ + p.ch)) * 1000) / 10],
    indice: "Population active = personnes en emploi + chômeurs. Taux de chômage = chômeurs ÷ population active × 100.",
    correction: (p) => { const a = p.occ + p.ch; return P(`Population active = ${fmt(p.occ)} + ${fmt(p.ch)} = <b>${fmt(a)}</b> personnes.`, `Taux de chômage = ${fmt(p.ch)} ÷ ${fmt(a)} × 100 ≈ <b>${fmt(100 * p.ch / a, 1)} %</b>.`, "Attention : on divise par la population <b>active</b>, et non par la population totale, qui comprend aussi les enfants, les étudiants et les retraités."); } },

  { id: "em1-points", theme: "emploi", niveau: 1, type: "calcul", notion: "taux-naturel",
    titre: "Points de pourcentage ou pourcentage ?", competence: "Distinguer un écart en points d’un écart en pourcentage.",
    gen: () => ({ a: pick([3.8, 4.2, 4.6, 5.1, 5.3, 6.0]), b: pick([2.0, 2.4, 2.7, 3.0]) }),
    enonce: (p) => P(`Le taux de chômage est de <b>${fmt(p.a, 1)} %</b> dans une région et de <b>${fmt(p.b, 1)} %</b> en moyenne nationale.`, "Calculez l’écart en points de pourcentage, puis de combien de pour cent le taux de la région est supérieur à la moyenne (arrondi à l’unité)."),
    champs: [{ label: "Écart", unite: "points", tol: 0.05 }, { label: "Plus élevé de", unite: "%", tol: 1 }],
    reponses: (p) => [Math.round((p.a - p.b) * 10) / 10, Math.round(((p.a - p.b) / p.b) * 100)],
    indice: "Écart en points = différence des deux taux. Écart en % = différence ÷ taux de référence × 100.",
    correction: (p) => P(`Écart en points : ${fmt(p.a, 1)} − ${fmt(p.b, 1)} = <b>${fmt(p.a - p.b, 1)} points de pourcentage</b>.`, `Écart relatif : ${fmt(p.a - p.b, 1)} ÷ ${fmt(p.b, 1)} × 100 ≈ <b>${fmt(100 * (p.a - p.b) / p.b, 0)} %</b>.`, `Les deux affirmations sont justes, mais elles ne disent pas la même chose : « le chômage est plus élevé de ${fmt(p.a - p.b, 1)} points » et « le chômage est ${fmt(100 * (p.a - p.b) / p.b, 0)} % plus élevé ». Les confondre est une erreur fréquente dans les médias.`) },


  { id: "em1-vf-types", theme: "emploi", niveau: 1, type: "vf", notion: "taux-naturel",
    titre: "Les formes de chômage", competence: "Associer une situation à une forme de chômage.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Une ingénieure qui a démissionné et prend trois mois pour trouver un poste qui lui convient est en chômage frictionnel.", true, "Le chômage frictionnel correspond au temps nécessaire pour passer d’un emploi à un autre."],
      ["Un ouvrier du textile qui ne trouve pas de travail parce que les entreprises de sa région cherchent des informaticiens est en chômage conjoncturel.", false, "C’est du chômage <b>structurel</b> : ses compétences ne correspondent pas aux emplois disponibles. Le chômage conjoncturel vient d’un manque général de demande."],
      ["Pendant une récession, quand les entreprises vendent moins et licencient, le chômage conjoncturel augmente.", true, "Le manque de débouchés pousse les entreprises à réduire leur production et leurs effectifs."],
      ["Même dans une économie en très bonne santé, le chômage ne descend jamais à zéro.", true, "Il reste toujours du chômage frictionnel et structurel : c’est l’idée du taux de chômage naturel."]
    ] },

  { id: "em1-seco-bit", theme: "emploi", niveau: 1, type: "qcm", notion: "taux-naturel",
    titre: "Deux façons de compter les chômeurs", competence: "Comprendre pourquoi deux statistiques du chômage diffèrent.",
    enonce: P("En Suisse, le SECO publie chaque mois un taux de chômage d’environ 2 à 3 %, tandis que l’Office fédéral de la statistique publie un taux au sens du BIT d’environ 4 à 5 %. Pourquoi cette différence ?"),
    options: ["Le SECO mesure le chômage chaque mois et le BIT une seule fois par an, d’où un décalage dans le temps.", "Le SECO ne compte que les chômeurs inscrits dans un office de placement, le BIT compte aussi ceux qui ne le sont pas.", "Le SECO ne compte que les chômeurs de nationalité suisse, alors que le BIT compte tous les résidents.", "Le BIT ajoute aux chômeurs les personnes à temps partiel qui voudraient travailler davantage."], c: 1, pourquoi: ["Le rythme de publication diffère, mais l’écart est permanent. Il vient de ce que les deux taux ne comptent pas les mêmes personnes.", null, "Le SECO compte toutes les personnes inscrites, suisses ou étrangères. La différence tient à l’inscription, pas à la nationalité.", "Les personnes en sous-emploi ont un emploi. Elles ne sont comptées comme chômeuses ni par le SECO ni par le BIT."],
    explication: P("Le taux du <b>SECO</b> repose sur les personnes <b>inscrites</b> dans un office régional de placement (ORP). Le taux au sens du <b>BIT</b>, calculé par l’OFS à partir de l’Enquête suisse sur la population active, compte toutes les personnes sans emploi qui cherchent et sont disponibles, <b>inscrites ou non</b> : par exemple celles qui n’ont pas droit aux indemnités ou ne s’inscrivent pas.", "Le chiffre du BIT permet les comparaisons internationales ; celui du SECO est publié plus rapidement et en détail par canton.") },

  { id: "em1-keynes", theme: "emploi", niveau: 1, type: "qcm", notion: "demande-effective",
    titre: "Le chômage selon Keynes", competence: "Identifier l’explication keynésienne du chômage.",
    enonce: P("Pendant la Grande Dépression, certains économistes recommandaient de baisser les salaires pour réduire le chômage. Quelle est la réponse de Keynes ?"),
    options: ["Il s’y oppose : des salaires plus bas réduisent la consommation, donc les débouchés des entreprises.", "Il approuve : des salaires plus bas rendent l’embauche plus rentable pour les entreprises.", "Il propose d’interdire les licenciements pendant les périodes de crise.", "Il estime que le chômage disparaîtra de lui-même en quelques semaines, par le jeu du marché."], c: 0, pourquoi: [null, "C’était la position de ses adversaires. Pour Keynes, baisser les salaires réduit aussi le pouvoir d’achat, donc les ventes des entreprises.", "Keynes ne propose pas d’interdire les licenciements : il veut soutenir la demande pour que les entreprises aient de nouveau besoin d’embaucher.", "C’est précisément ce que Keynes conteste : une économie peut rester longtemps avec un chômage élevé si la demande manque."],
    explication: P("Pour <b>Keynes</b>, les entreprises n’embauchent pas parce qu’elles ne vendent pas : le chômage vient d’une <b>demande effective</b> insuffisante. Baisser les salaires, c’est aussi baisser le pouvoir d’achat des salariés, donc la demande, ce qui peut aggraver la situation.", "Il recommande de soutenir la demande, si nécessaire par des dépenses publiques, dont l’effet est amplifié par le multiplicateur.") },

  { id: "em1-rht", theme: "emploi", niveau: 1, type: "qcm", notion: "hysterese",
    titre: "La réduction de l’horaire de travail", competence: "Comprendre un instrument suisse de politique de l’emploi.",
    enonce: P("Pendant la pandémie de 2020, des centaines de milliers de salariés suisses ont été placés en « réduction de l’horaire de travail » (RHT) : l’assurance chômage compensait une grande partie des heures non travaillées. Quel était l’objectif principal ?"),
    options: ["Inciter les salariés concernés à chercher un emploi dans une branche qui recrute.", "Éviter les licenciements pendant une baisse temporaire d’activité, en gardant les compétences dans l’entreprise.", "Partager le travail disponible entre davantage de personnes, pour créer des emplois.", "Remplacer l’indemnité de chômage par une aide moins coûteuse pour l’assurance."], c: 1, pourquoi: ["La RHT sert au contraire à garder les salariés dans leur emploi et dans leur entreprise.", null, "La RHT ne crée pas d’emplois nouveaux. Elle maintient les emplois existants pendant que l’activité est réduite.", "La RHT est une prestation de l’assurance chômage, qui en supporte le coût. Son but est d’éviter des licenciements, pas de faire des économies."],
    explication: P("La RHT permet à une entreprise touchée par une baisse <b>temporaire</b> d’activité de réduire le temps de travail plutôt que de licencier. Les salariés gardent leur emploi et leurs liens avec l’entreprise ; l’entreprise conserve ses compétences et peut redémarrer vite.", "Elle limite ainsi l’<b>hystérèse</b> : le risque qu’un chômage temporaire devienne durable. Son inconvénient est de pouvoir maintenir trop longtemps des emplois dans des activités qui déclinent.") },

  { id: "em1-tableau", theme: "emploi", niveau: 1, type: "document", notion: "taux-naturel",
    titre: "Du taux de chômage au nombre de chômeurs", competence: "Passer d’un taux de chômage au nombre de chômeurs en tenant compte de la taille de la population active.",
    enonce: P("Le tableau donne le taux de chômage et la population active de trois régions d’un même pays :") +
      `<table><thead><tr><th>Région</th><th>Taux de chômage</th><th>Population active</th></tr></thead><tbody><tr><td>A</td><td>4 %</td><td>6 000 000</td></tr><tr><td>B</td><td>8 %</td><td>1 000 000</td></tr><tr><td>C</td><td>6 %</td><td>2 000 000</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Quelle affirmation est correcte ?"),
    options: ["La région B compte le plus de chômeurs, puisque son taux est le plus élevé.", "La région A compte le plus de chômeurs, bien que son taux soit le plus bas.", "Les trois régions réunies ont un taux de chômage de 18 %, somme des trois taux.", "La région C compte deux fois plus de chômeurs que B, car sa population active est deux fois plus grande."], c: 1, pourquoi: ["Un taux élevé ne suffit pas : la région B compte 8 % de 1 000 000, soit 80 000 chômeurs, bien moins que la région A.", null, "On ne peut pas additionner des taux calculés sur des populations différentes. Le taux d’ensemble est de 440 000 chômeurs sur 9 000 000 d’actifs, soit environ 4,9 %.", "La région C compte 6 % de 2 000 000, soit 120 000 chômeurs, contre 80 000 pour B. Le rapport est de 1,5, pas de 2, car les deux taux ne sont pas les mêmes."],
    explication: P("Le nombre de chômeurs est le taux multiplié par la population active : 4 % de 6 000 000 = <b>240 000</b> pour la région A, 8 % de 1 000 000 = 80 000 pour B et 6 % de 2 000 000 = 120 000 pour C.", "Un taux dit la fréquence du chômage, pas le nombre de personnes touchées. La région où le taux est le plus bas est ici celle qui compte le plus de chômeurs, parce que sa population active est six fois plus grande que celle de B.") },

  /* =========================== NIVEAU 2 : INTERMÉDIAIRE =========================== */
  { id: "em2-flux", theme: "emploi", niveau: 2, type: "calcul", notion: "taux-naturel",
    titre: "Les flux du chômage", competence: "Calculer l’évolution du chômage à partir des entrées et des sorties.",
    gen: () => { const u0 = rnd(100, 160) * 1000, ent = rnd(20, 35) * 1000, sor = rnd(18, 36) * 1000, pa = rnd(48, 52) * 100000; return { u0, ent, sor, pa }; },
    enonce: (p) => P(`Au début du mois, un pays compte <b>${fmt(p.u0)}</b> chômeurs. Pendant le mois, <b>${fmt(p.ent)}</b> personnes deviennent chômeuses et <b>${fmt(p.sor)}</b> sortent du chômage. La population active est de <b>${fmt(p.pa)}</b> personnes.`, "Combien y a-t-il de chômeurs à la fin du mois, et quel est le taux de chômage (arrondi à deux décimales) ?"),
    champs: [{ label: "Chômeurs", unite: "personnes", tol: 0.5 }, { label: "Taux", unite: "%", tol: 0.011 }],
    reponses: (p) => { const u = p.u0 + p.ent - p.sor; return [u, Math.round((u / p.pa) * 10000) / 100]; },
    indice: "Chômeurs en fin de mois = chômeurs au début + entrées − sorties.",
    correction: (p) => { const u = p.u0 + p.ent - p.sor; return P(`Chômeurs en fin de mois = ${fmt(p.u0)} + ${fmt(p.ent)} − ${fmt(p.sor)} = <b>${fmt(u)}</b>.`, `Taux = ${fmt(u)} ÷ ${fmt(p.pa)} × 100 ≈ <b>${fmt(100 * u / p.pa, 2)} %</b>.`, `Le solde (${fmt(p.ent - p.sor)}) est petit comparé aux flux : chaque mois, des dizaines de milliers de personnes entrent au chômage et en sortent. Le taux de chômage n’est que le résultat de ce mouvement permanent.`); } },

  { id: "em2-okun", theme: "emploi", niveau: 2, type: "calcul", notion: "demande-effective",
    titre: "La loi d’Okun", competence: "Relier croissance et variation du chômage.",
    gen: () => ({ g: pick([-3, -1, 0, 1, 1.5, 3, 4]), u0: pick([4.5, 5.5, 6.5, 7.5]) }),
    enonce: (p) => P("Dans un pays, la loi d’Okun est estimée ainsi : <b>variation du taux de chômage = −0,5 × (croissance du PIB − 2)</b>, en points de pourcentage. Autrement dit, il faut une croissance de 2 % pour que le chômage reste stable.", `Cette année, la croissance est de <b>${fmt(p.g)} %</b>, et le taux de chômage était de <b>${fmt(p.u0, 1)} %</b> en début d’année. De combien de points le taux de chômage varie-t-il (signe moins s’il baisse), et quel est son niveau à la fin de l’année ? Arrondissez à deux décimales.`),
    champs: [{ label: "Variation", unite: "points", tol: 0.01 }, { label: "Taux en fin d’année", unite: "%", tol: 0.01 }],
    reponses: (p) => [X.arr(0.5 * (2 - p.g), 2), X.arr(p.u0 + 0.5 * (2 - p.g), 2)],
    indice: "Remplacez la croissance dans la formule et faites attention aux signes. Le taux de fin d’année est le taux de début d’année plus la variation.",
    correction: (p) => { const v = 0.5 * (2 - p.g); return P(`Variation = −0,5 × (${fmt(p.g)} − 2) = −0,5 × (${fmt(p.g - 2)})`, `= <b>${fmt(v)} point${Math.abs(v) > 1 ? "s" : ""}</b>.`, `Taux en fin d’année = ${fmt(p.u0, 1)} ${v < 0 ? "−" : "+"} ${fmt(Math.abs(v))} = <b>${fmt(p.u0 + v, 2)} %</b>.`, v > 0 ? "La croissance est inférieure à 2 % : elle ne suffit pas à absorber la hausse de la productivité et de la population active, et le chômage augmente." : v < 0 ? "La croissance dépasse 2 % : les entreprises embauchent davantage, et le chômage baisse." : "La croissance est juste suffisante pour maintenir le chômage stable.", "L’économiste Arthur Okun a mis en évidence cette relation aux États-Unis en 1962. Ses coefficients varient selon les pays et les époques."); } },

  { id: "em2-salaire-min", theme: "emploi", niveau: 2, type: "qcm", notion: "concurrence-imparfaite",
    titre: "Le salaire minimum dans le modèle concurrentiel", competence: "Appliquer le raisonnement d’offre et de demande au marché du travail.",
    enonce: P("Sur un marché du travail parfaitement concurrentiel, le salaire d’équilibre des serveurs est de 21 francs de l’heure. Le canton fixe un salaire minimum de 24 francs. Que prévoit le modèle ?"),
    options: ["Le nombre de personnes prêtes à travailler augmente et les employeurs veulent embaucher moins : un chômage apparaît.", "L’emploi augmente, car les salariés dépensent plus.", "Rien ne change, car le salaire minimum est inférieur à l’équilibre.", "Le salaire de marché redescend à 21 francs."], c: 0, pourquoi: [null, "Le modèle concurrentiel ne tient pas compte de cet effet sur la demande : il prévoit moins d’embauches à 24 francs.", "Le salaire minimum de 24 francs est supérieur au salaire d’équilibre de 21 francs : il s’applique bien.", "La loi interdit de payer moins de 24 francs : le salaire ne peut pas redescendre à 21 francs."],
    explication: P("Dans le modèle concurrentiel, le salaire minimum est un <b>prix plancher</b> au-dessus de l’équilibre : plus de personnes veulent travailler, mais les employeurs demandent moins de travail. L’écart est du chômage.", "Les études empiriques nuancent cette prédiction : quand les employeurs ont un pouvoir de marché (<b>monopsone</b>), un salaire minimum modéré peut ne pas réduire l’emploi, voire l’augmenter. Genève et Neuchâtel ont des salaires minimaux cantonaux parmi les plus élevés du monde.") },

  { id: "em2-vf-hysterese", theme: "emploi", niveau: 2, type: "vf", notion: "hysterese",
    titre: "Le chômage de longue durée", competence: "Comprendre pourquoi le chômage peut devenir persistant.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Plus une personne reste longtemps au chômage, plus il lui est difficile de retrouver un emploi.", true, "Elle perd des compétences, des contacts professionnels et parfois confiance ; certains employeurs se méfient des longues interruptions."],
      ["Selon la théorie de l’hystérèse, le chômage revient de lui-même à son niveau initial après une récession.", false, "C’est l’inverse : selon Blanchard et Summers (1986), une récession peut laisser des traces durables, car le chômage d’aujourd’hui augmente le chômage de demain."],
      ["Selon la théorie des insiders et des outsiders, les chômeurs de longue durée pèsent peu sur les négociations salariales.", true, "Ils sont moins considérés comme des concurrents par les salariés en place (les « insiders »), qui peuvent obtenir des hausses de salaires malgré le chômage."],
      ["Des politiques de formation et d’accompagnement peuvent réduire le chômage de longue durée.", true, "C’est le rôle des mesures actives du marché du travail, comme celles proposées par les offices régionaux de placement en Suisse."]
    ] },

  { id: "em2-appariement", theme: "emploi", niveau: 2, type: "qcm", notion: "taux-naturel",
    titre: "Des chômeurs et des postes vacants", competence: "Expliquer la coexistence de chômage et d’emplois non pourvus.",
    enonce: P("En Suisse, de nombreux employeurs disent ne pas trouver de personnel, par exemple dans les soins, l’informatique ou la construction, alors que plus de 100 000 personnes sont inscrites au chômage. Comment l’expliquer ?"),
    options: ["Le chômage vient d’un manque général de demande, les entreprises n’ayant pas assez de commandes pour embaucher.", "Les indemnités de chômage sont trop généreuses, et la plupart des chômeurs préfèrent ne pas travailler.", "Les postes et les chômeurs ne se correspondent pas toujours, par la qualification ou la région, et la rencontre prend du temps.", "Les statistiques se trompent, les postes annoncés comme vacants étant en réalité déjà pourvus."], c: 2, pourquoi: ["Un manque général de demande expliquerait le chômage, pas les postes vacants. Si des employeurs cherchent du personnel, c’est que la demande est là.", "Les indemnités peuvent allonger un peu la recherche, mais la grande majorité des chômeurs cherchent un emploi. Le décalage entre les postes et les profils explique mieux les postes vacants.", null, "Les postes vacants sont recensés et souvent réels : les pénuries dans les soins ou l’informatique sont bien documentées."],
    explication: P("C’est un problème d’<b>appariement</b> : les postes vacants et les chômeurs ne se correspondent pas toujours, par la qualification, le lieu, les horaires ou le salaire, et il faut du temps pour qu’ils se trouvent. Diamond, Mortensen et Pissarides ont reçu le Nobel en 2010 pour l’analyse de ces frictions.", "Les remèdes sont la formation, la mobilité, de meilleurs services de placement, et parfois l’amélioration des conditions de travail dans les métiers en pénurie.") },

  { id: "em2-duree", theme: "emploi", niveau: 2, type: "calcul", notion: "hysterese",
    titre: "La durée moyenne du chômage", competence: "Relier un taux de sortie à une durée moyenne.",
    gen: () => ({ s: pick([8, 12.5, 20, 25, 40]), e: pick([12000, 15000, 20000, 24000]) }),
    enonce: (p) => P(`Chaque mois, <b>${fmt(p.s)} %</b> des chômeurs retrouvent un emploi (ou sortent du chômage). On suppose que cette probabilité est la même pour tous.`, `Chaque mois, <b>${fmt(p.e)}</b> personnes deviennent chômeuses, et le nombre de chômeurs est stable. Quelle est la durée moyenne d’un épisode de chômage, en mois (arrondie à une décimale) ? Combien de chômeurs compte alors le pays ?`),
    champs: [{ label: "Durée moyenne", unite: "mois", tol: 0.05 }, { label: "Nombre de chômeurs", unite: "personnes", tol: 1 }],
    reponses: (p) => [X.arr(100 / p.s, 1), Math.round(p.e * 100 / p.s)],
    indice: "Exprimez d’abord la probabilité en fraction (20 % = 0,2), puis prenez-en l’inverse. Quand le chômage est stable, les sorties mensuelles sont égales aux entrées.",
    correction: (p) => P(`Durée moyenne = 1 ÷ probabilité de sortie = 1 ÷ ${fmt(p.s / 100, 3)}`, `= <b>${fmt(100 / p.s, 1)} mois</b>.`, `Chômage stable : sorties = entrées, donc ${fmt(p.s / 100, 3)} × chômeurs = ${fmt(p.e)}, soit chômeurs = ${fmt(p.e)} ÷ ${fmt(p.s / 100, 3)} = <b>${fmt(Math.round(p.e * 100 / p.s))}</b>. C’est le flux d’entrée multiplié par la durée moyenne.`, "Si la probabilité de sortie baisse, par exemple pendant une récession, la durée moyenne du chômage s’allonge et le risque de chômage de longue durée augmente. En réalité, la probabilité de sortie diminue souvent avec l’ancienneté au chômage, ce qui aggrave l’hystérèse.") },

  { id: "em2-jeunes", theme: "emploi", niveau: 2, type: "redaction", notion: "taux-naturel",
    titre: "Le chômage des jeunes en Suisse", competence: "Expliquer une différence entre pays.",
    enonce: P("Dans plusieurs pays européens, comme l’Espagne, l’Italie ou la France, le chômage des 15-24 ans dépasse souvent 15 ou 20 %. En Suisse, il reste nettement plus bas.", "<b>Consigne :</b> proposez une explication de cette différence. Présentez le rôle de la formation professionnelle et au moins un autre facteur, montrez par quel mécanisme ils réduisent le chômage des jeunes, indiquez une limite de cette comparaison, puis concluez en une phrase. Longueur attendue, 10 à 15 lignes."),
    criteres: ["La réponse mobilise la formation professionnelle duale (apprentissage en entreprise et à l’école).", "Elle explique le mécanisme : expérience professionnelle, compétences adaptées aux besoins des entreprises, transition directe vers l’emploi, réseau…", "Elle cite au moins un autre facteur : marché du travail flexible, bonne conjoncture, faible chômage général, partenariat social…", "Elle mentionne une limite ou une nuance : différences de mesure (SECO, BIT), jeunes sans formation, difficultés après l’apprentissage…", "Elle se termine par une phrase de conclusion qui répond à la question posée."],
    corrige: P("Le principal facteur est la <b>formation professionnelle duale</b> : environ deux tiers des jeunes Suisses suivent un apprentissage, partagé entre l’entreprise et l’école professionnelle. Ils acquièrent une expérience reconnue et des compétences adaptées aux besoins des employeurs, et beaucoup sont engagés par leur entreprise formatrice. La transition entre l’école et l’emploi, très difficile dans d’autres pays, est ainsi facilitée.", "D’autres facteurs jouent : un marché du travail plutôt flexible, qui facilite l’embauche, un chômage général faible et une économie prospère, ainsi qu’un partenariat social qui associe les entreprises à l’organisation des formations.", "Il faut toutefois nuancer : selon la définition du BIT, le chômage des jeunes est plus élevé que selon les chiffres du SECO, et les jeunes sans formation après l’école obligatoire restent nettement plus exposés.") },

  { id: "em2-nairu", theme: "emploi", niveau: 2, type: "qcm", notion: "courbe-phillips",
    titre: "Relancer au-delà du chômage naturel", competence: "Appliquer l’analyse de Friedman et Phelps.",
    enonce: P("Le taux de chômage d’un pays est égal à son taux de chômage naturel, estimé à 4 %. Le gouvernement veut le faire descendre à 2 % par une forte relance de la demande. Selon Friedman et Phelps, que va-t-il se passer ?"),
    options: ["Le chômage restera durablement à 2 %, au prix d’une inflation modérée et stable.", "Le chômage baissera temporairement, mais l’inflation accélérera et le chômage reviendra vers 4 %.", "Le chômage augmentera dès le départ, car la relance fait monter les prix.", "L’inflation baissera, car la production augmente et les coûts unitaires diminuent."], c: 1, pourquoi: ["Selon Friedman et Phelps, on ne peut pas maintenir durablement le chômage sous son taux naturel par la demande.", null, "À court terme, la relance réduit le chômage : c’est seulement ensuite qu’il revient vers 4 %.", "Une forte relance accélère l’inflation : la demande augmente plus vite que la production."],
    explication: P("À court terme, la relance peut réduire le chômage, car les salaires et les anticipations ne s’ajustent pas tout de suite. Mais quand les salariés constatent l’inflation, ils réclament des hausses de salaires, et l’embauche revient à son niveau initial : le chômage retourne vers son <b>taux naturel</b>, avec une inflation plus élevée.", "Dans ce cadre, réduire durablement le chômage suppose d’agir sur ses causes structurelles, à savoir la formation, l’appariement et les règles du marché du travail. Cette conclusion est discutée. Pour les tenants de l’hystérèse et pour les post-keynésiens, le taux naturel dépend lui-même de la demande passée, et une économie maintenue longtemps en haute conjoncture peut le faire baisser.") },

  /* =========================== NIVEAU 3 : AVANCÉ =========================== */
  { id: "em3-equilibre", theme: "emploi", niveau: 3, type: "calcul", notion: "taux-naturel",
    titre: "Le chômage d’équilibre des flux", competence: "Calculer le taux de chômage stationnaire à partir des taux de transition.",
    gen: () => ({ s: pick([0.8, 1, 1.2, 1.5, 2, 2.5]), f: pick([15, 20, 25, 30, 40]) }),
    enonce: (p) => P(`Chaque mois, <b>${fmt(p.s)} %</b> des personnes en emploi perdent leur emploi (taux de séparation s), et <b>${fmt(p.f)} %</b> des chômeurs en retrouvent un (taux de retour à l’emploi f).`, "À long terme, le chômage se stabilise quand le nombre de personnes qui perdent leur emploi est égal au nombre de chômeurs qui en retrouvent un. Écrivez cette égalité pour une population active égale à 1, puis calculez le taux de chômage d’équilibre u*. Calculez ensuite le nouveau taux d’équilibre si le taux de retour à l’emploi f augmentait de 10 points. Arrondissez les deux taux à deux décimales."),
    champs: [{ label: "u*", unite: "%", tol: 0.011 }, { label: "u* si f augmente de 10 points", unite: "%", tol: 0.011 }],
    reponses: (p) => [X.arr(100 * p.s / (p.s + p.f), 2), X.arr(100 * p.s / (p.s + p.f + 10), 2)],
    indice: "Si u est le taux de chômage, les entrées au chômage valent s × (1 − u) et les sorties f × u. Utilisez s et f sous la même forme (en % ou en fraction).",
    correction: (p) => { const u = p.s / (p.s + p.f), u2 = p.s / (p.s + p.f + 10); return P(`Entrées au chômage : s × (1 − u). Sorties du chômage : f × u. À l’équilibre, s × (1 − u) = f × u, donc s = (s + f) × u, donc u* = s ÷ (s + f).`, `u* = ${fmt(p.s)} ÷ (${fmt(p.s)} + ${fmt(p.f)}) ≈ <b>${fmt(100 * u, 2)} %</b>.`, `Avec f = ${fmt(p.f + 10)} %, u* = ${fmt(p.s)} ÷ (${fmt(p.s)} + ${fmt(p.f + 10)}) ≈ <b>${fmt(100 * u2, 2)} %</b>, soit ${fmt(100 * (u - u2), 2)} point de moins.`, "Pour réduire ce chômage, il faut soit réduire les séparations (stabilité de l’emploi), soit accélérer le retour à l’emploi (placement, formation, incitations). C’est l’intuition de la théorie de la recherche d’emploi."); } },

  { id: "em3-okun-inverse", theme: "emploi", niveau: 3, type: "calcul", notion: "demande-effective",
    titre: "Quelle croissance pour réduire le chômage ?", competence: "Estimer une relation d’Okun à partir de deux observations, puis l’utiliser à l’envers.",
    gen: () => { const k = pick([0.4, 0.5]), seuil = pick([1.5, 2, 2.5]), a = pick([1.2, 2.2, 2.6]), b = pick([2, 2.5, 3]); return { k, seuil, g1: seuil + a, g2: seuil - b, d1: X.arr(-k * a, 2), d2: X.arr(k * b, 2), d: pick([0.6, 0.8, 1.2]) }; },
    enonce: (p) => P("Dans un pays, la variation annuelle du taux de chômage est reliée à la croissance du PIB par une relation linéaire : le chômage reste stable à un certain taux de croissance, et il varie proportionnellement à l’écart avec ce taux. Deux années sont observées.") +
      `<table><thead><tr><th></th><th>Croissance du PIB</th><th>Variation du taux de chômage</th></tr></thead><tbody><tr><td>Première année</td><td>${fmt(p.g1)} %</td><td>${fmt(p.d1)} point</td></tr><tr><td>Seconde année</td><td>${fmt(p.g2)} %</td><td>${fmt(p.d2)} point</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P(`Déterminez de combien de points le chômage baisse pour chaque point de croissance supplémentaire (coefficient d’Okun, en valeur positive), puis le taux de croissance qui stabilise le chômage. Le gouvernement veut ensuite faire baisser le taux de chômage de <b>${fmt(p.d)} point</b> en un an : quelle croissance faut-il ? Arrondissez à deux décimales.`),
    champs: [{ label: "Coefficient d’Okun", unite: "point par point de croissance", tol: 0.005 }, { label: "Croissance qui stabilise le chômage", unite: "%", tol: 0.011 }, { label: "Croissance nécessaire", unite: "%", tol: 0.011 }],
    reponses: (p) => [p.k, p.seuil, X.arr(p.seuil + p.d / p.k, 2)],
    indice: "Entre les deux années, la croissance et la variation du chômage changent : le rapport des deux écarts donne la pente. Le chômage est stable quand sa variation est nulle.",
    correction: (p) => { const g = p.seuil + p.d / p.k; return P(`Pente : (${fmt(p.d1)} − ${fmt(p.d2)}) ÷ (${fmt(p.g1)} − ${p.g2 < 0 ? "(" + fmt(p.g2) + ")" : fmt(p.g2)}) = ${fmt(X.arr(p.d1 - p.d2, 2), 2)} ÷ ${fmt(p.g1 - p.g2)} = −${fmt(p.k)}. Le coefficient d’Okun vaut <b>${fmt(p.k)}</b> : un point de croissance en plus fait baisser le chômage de ${fmt(p.k)} point.`, `Croissance qui stabilise le chômage : ${fmt(p.d1)} = −${fmt(p.k)} × (${fmt(p.g1)} − g*), donc g* = ${fmt(p.g1)} − ${fmt(-p.d1)} ÷ ${fmt(p.k)} = <b>${fmt(p.seuil)} %</b>.`, `On veut −${fmt(p.k)} × (g − ${fmt(p.seuil)}) = −${fmt(p.d)}, donc g − ${fmt(p.seuil)} = ${fmt(p.d)} ÷ ${fmt(p.k)} = ${fmt(p.d / p.k, 3)}, et g = <b>${fmt(g)} %</b>.`, "Une baisse rapide du chômage demande une croissance nettement supérieure à la croissance « normale », ce qui est rarement durable sans tension sur les prix."); } },

  { id: "em3-monopsone", theme: "emploi", niveau: 3, type: "calcul", notion: "concurrence-imparfaite",
    titre: "Le monopsone", competence: "Calculer l’emploi et le salaire d’un employeur dominant.",
    gen: () => { const b = pick([0.5, 1]); const a = rnd(20, 26); const Lm = rnd(8, 16) * (b === 0.5 ? 2 : 1); const v = a + 2 * b * Lm; return { a, b, Lm, v }; },
    enonce: (p) => P(`Un hôpital régional est le seul grand employeur d’infirmiers de sa vallée. Pour attirer L infirmiers, il doit payer un salaire horaire <b>w = ${p.a} + ${fmt(p.b)}L</b> à tous. Chaque infirmier rapporte à l’hôpital <b>${p.v} francs</b> de l’heure (productivité en valeur).`, "Établissez le coût marginal du travail à partir de la dépense salariale totale, puis calculez le nombre d’infirmiers que l’hôpital embauche et le salaire qu’il paie. Calculez ensuite l’emploi qu’on observerait si le marché était concurrentiel (salaire égal à la productivité), et le taux d’exploitation (v − w) ÷ w, où v est la productivité en valeur et w le salaire. Arrondissez le taux d’exploitation à une décimale."),
    champs: [{ label: "Emploi L", unite: "personnes", tol: 0.05 }, { label: "Salaire w", unite: "fr./h", tol: 0.05 }, { label: "Emploi en concurrence", unite: "personnes", tol: 0.05 }, { label: "Taux d’exploitation", unite: "%", tol: 0.1 }],
    reponses: (p) => [p.Lm, p.a + p.b * p.Lm, 2 * p.Lm, X.arr(100 * (p.v - p.a - p.b * p.Lm) / (p.a + p.b * p.Lm), 1)],
    indice: "La dépense salariale est w × L, avec w qui dépend de L. Le coût d’un infirmier de plus est la dérivée de cette dépense. L’hôpital embauche jusqu’à ce que ce coût marginal soit égal à la productivité en valeur.",
    correction: (p) => { const w = p.a + p.b * p.Lm, Lc = (p.v - p.a) / p.b; return P(`Dépense salariale : w × L = (${p.a} + ${fmt(p.b)}L) × L = ${p.a}L + ${fmt(p.b)}L². Sa dérivée donne le coût marginal du travail : <b>${p.a} + ${fmt(2 * p.b)}L</b>. Il dépasse le salaire, car la hausse accordée à tous les autres s’ajoute au salaire du nouvel infirmier.`, `Condition : ${p.a} + ${fmt(2 * p.b)}L = ${p.v}, donc L = (${p.v} − ${p.a}) ÷ ${fmt(2 * p.b)} = <b>${p.Lm} infirmiers</b>.`, `Salaire : w = ${p.a} + ${fmt(p.b)} × ${p.Lm} = <b>${fmt(w)} francs</b> de l’heure, bien en dessous de ce que rapporte un infirmier (${p.v} francs).`, `En concurrence, le salaire serait égal à ${p.v} francs : ${p.a} + ${fmt(p.b)}L = ${p.v} donne L = <b>${fmt(Lc)} infirmiers</b>, soit le double.`, `Taux d’exploitation : (${p.v} − ${fmt(w)}) ÷ ${fmt(w)} ≈ <b>${fmt(100 * (p.v - w) / w, 1)} %</b>. Il est égal à l’inverse de l’élasticité de l’offre de travail au point choisi : plus l’offre réagit peu au salaire, plus l’employeur peut payer en dessous de la productivité. C’est l’analyse de Joan Robinson (1933).`); } },

  { id: "em3-card-krueger", theme: "emploi", niveau: 3, type: "qcm", notion: "concurrence-imparfaite",
    titre: "Une expérience naturelle", competence: "Comprendre la méthode des doubles différences.",
    enonce: P("En 1992, le New Jersey augmente son salaire minimum, mais pas la Pennsylvanie voisine. David Card et Alan Krueger comparent l’emploi dans les fast-foods des deux côtés de la frontière, avant et après la hausse. Pourquoi comparer avec la Pennsylvanie, plutôt que d’observer seulement le New Jersey ?"),
    options: ["Parce que les fast-foods de Pennsylvanie sont plus nombreux, ce qui rend l’échantillon plus fiable.", "Pour isoler l’effet du salaire minimum : la Pennsylvanie montre ce qui se serait passé sans la hausse.", "Parce que la loi fédérale impose de comparer les États voisins.", "Pour mesurer l’effet du salaire minimum sur les prix pratiqués en Pennsylvanie."], c: 1, pourquoi: ["Le nombre de restaurants ne compte pas : ce qui importe, c’est que la Pennsylvanie soit semblable mais sans hausse.", null, "Aucune loi n’impose cette méthode : c’est un choix scientifique pour isoler l’effet du salaire minimum.", "La Pennsylvanie n’a pas changé son salaire minimum : elle sert de point de comparaison, pas d’objet d’étude."],
    explication: P("L’emploi au New Jersey a pu évoluer pour bien d’autres raisons que le salaire minimum : conjoncture, saison, goûts des consommateurs. La Pennsylvanie, très semblable mais sans hausse, sert de <b>groupe de contrôle</b>. L’effet estimé est la différence entre l’évolution au New Jersey et l’évolution en Pennsylvanie : c’est la méthode des <b>doubles différences</b>.", "Card et Krueger n’ont pas trouvé de baisse de l’emploi. La méthode repose sur l’hypothèse des tendances parallèles. Sans la hausse du salaire minimum, l’emploi aurait évolué de la même façon dans les deux États. Le résultat a été contesté. Avec des données de paie, David Neumark et William Wascher ont obtenu en 2000 un effet négatif, auquel Card et Krueger ont répondu par de nouvelles données. Card a reçu le Nobel en 2021 pour ces méthodes, qui permettent de tirer des conclusions causales d’« expériences naturelles ».") },

  { id: "em3-vf-theories", theme: "emploi", niveau: 3, type: "vf", notion: "taux-naturel",
    titre: "Les théories du marché du travail", competence: "Prévoir ce que chaque théorie du marché du travail annonce dans un cas donné.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Dans un pays où les salariés en place sont très protégés et bien syndiqués, la théorie des « insiders-outsiders » prévoit que le chômage fait baisser rapidement les salaires.", false, "C’est l’inverse : les salariés en place (insiders) ont un pouvoir de négociation, car les remplacer coûte cher, et peuvent maintenir des salaires élevés malgré la présence de chômeurs (outsiders)."],
      ["Dans une entreprise où l’effort des salariés est difficile à contrôler, la théorie du salaire d’efficience prévoit qu’elle peut garder un salaire supérieur à celui du marché, même si des candidats acceptent moins.", true, "Un salaire plus élevé rend un licenciement plus coûteux pour le salarié, le motive, le fidélise et attire de meilleurs candidats. Le salaire au-dessus du marché devient rentable pour l’entreprise, et il contribue à un chômage d’équilibre."],
      ["Dans un modèle de recherche d’emploi, une hausse de l’indemnité de chômage raccourcit, toutes choses égales d’ailleurs, la durée moyenne du chômage.", false, "Elle tend à l’allonger, car elle relève le salaire minimal que le chômeur accepte. Elle peut en contrepartie permettre de chercher un emploi mieux adapté, ce qui améliore l’appariement."],
      ["Le modèle danois de « flexicurité » combine licenciements faciles, indemnisation généreuse et accompagnement intensif des chômeurs.", true, "Il vise à concilier la flexibilité pour les entreprises et la sécurité pour les travailleurs."]
    ] },

  { id: "em3-indemnite", theme: "emploi", niveau: 3, type: "calcul",
    titre: "L’indemnité de chômage en Suisse", competence: "Appliquer une règle de calcul d’une assurance sociale (version simplifiée).",
    gen: () => { const sal = pick([4800, 7500, 11000, 13500, 15000, 16500, 18000, 21000]); return { sal, enfants: pick([true, false]), offre: Math.round(sal * pick([0.6, 0.75, 0.9])) }; },
    enonce: (p) => P("Version simplifiée de la règle suisse : l’assurance chômage verse <b>70 %</b> du salaire assuré, ou <b>80 %</b> pour les personnes qui ont des enfants à charge (ou un salaire bas, ce qu’on ignore ici). Le salaire assuré est plafonné à <b>12 350 francs</b> par mois.", `Une personne gagnait <b>${fmt(p.sal)} francs</b> par mois et ${p.enfants ? "<b>a des enfants à charge</b>" : "<b>n’a pas d’enfant à charge</b>"}. Quelle est son indemnité mensuelle, et quel pourcentage de son ancien salaire représente-t-elle (arrondi à l’unité) ?`, `Elle reçoit une offre d’emploi à <b>${fmt(p.offre)} francs</b> par mois. Les cotisations sociales sont laissées de côté. De combien son revenu mensuel varie-t-il si elle accepte (signe moins s’il baisse) ? Reprendre cet emploi améliore-t-il son revenu ?`),
    champs: [{ label: "Indemnité", unite: "fr.", tol: 1 }, { label: "Part de l’ancien salaire", unite: "%", tol: 1 }, { label: "Variation du revenu si elle accepte", unite: "fr.", tol: 1 }, { label: "Reprendre l’emploi améliore-t-il son revenu ?", choix: ["Oui", "Non"] }],
    reponses: (p) => { const t = p.enfants ? 0.8 : 0.7, ind = t * Math.min(p.sal, 12350); return [Math.round(ind), Math.round((ind / p.sal) * 100), Math.round(p.offre - ind), p.offre > ind ? 0 : 1]; },
    indice: "Prenez d’abord le salaire assuré (le salaire, ou 12 350 francs s’il est plus élevé), puis appliquez le taux. Comparez ensuite l’indemnité à l’offre d’emploi.",
    correction: (p) => { const t = p.enfants ? 0.8 : 0.7, base = Math.min(p.sal, 12350), ind = t * base; return P(`Salaire assuré : ${p.sal > 12350 ? `le salaire dépasse le plafond, on retient 12 350 francs` : `${fmt(p.sal)} francs (sous le plafond)`}.`, `Indemnité : ${fmt(t * 100)} % × ${fmt(base)} = <b>${fmt(Math.round(ind))} francs</b>, soit <b>${fmt(Math.round(100 * ind / p.sal))} %</b> de l’ancien salaire.`, "Ce rapport s’appelle le <b>taux de remplacement</b>. Le plafond le réduit pour les hauts salaires. Le taux de 80 % s’applique aussi aux gains assurés inférieurs à 3 800 francs par mois environ. Dans la réalité, l’indemnité est calculée par jour, sa durée dépend de l’âge et de la durée de cotisation, et des cotisations sociales en sont déduites.", `Offre d’emploi : ${fmt(p.offre)} − ${fmt(Math.round(ind))} = <b>${fmt(Math.round(p.offre - ind))} francs</b> par mois${p.offre > ind ? ", le revenu augmente" : ", le revenu baisse : accepter est financièrement moins avantageux que de rester indemnisé"}.`, "Plus le taux de remplacement est élevé, plus la reprise d’emploi rapporte peu. Les modèles de recherche d’emploi en tirent que l’indemnité relève le salaire que le chômeur exige pour accepter un poste, et qu’elle allonge en moyenne la durée du chômage. C’est pourquoi les systèmes d’assurance chômage plafonnent l’indemnité, la limitent dans le temps et la combinent avec un accompagnement de la recherche."); } },

  { id: "em3-ia", theme: "emploi", niveau: 3, type: "redaction", notion: "destruction-creatrice",
    titre: "L’intelligence artificielle va-t-elle créer un chômage de masse ?", competence: "Construire une argumentation sur le progrès technique et l’emploi.",
    enonce: P("Les outils d’intelligence artificielle savent désormais rédiger, traduire, programmer ou analyser des documents, des tâches réservées jusqu’ici à des emplois qualifiés. Certains annoncent un chômage de masse ; d’autres rappellent que les révolutions techniques passées ont finalement créé plus d’emplois qu’elles n’en ont détruits.", "<b>Consigne :</b> l’intelligence artificielle va-t-elle provoquer un chômage de masse ? Présentez les arguments des deux camps, en mobilisant au moins une notion d’économie. Rattachez chaque position à une école ou à un auteur, et dites sur quelle hypothèse ils s’opposent. Indiquez ce que les pouvoirs publics peuvent faire, puis concluez. Longueur attendue, 15 à 25 lignes."),
    criteres: ["La réponse nomme au moins deux écoles ou auteurs et l’hypothèse qui les sépare.", "La réponse présente l’argument optimiste : destruction créatrice, nouveaux métiers, gains de productivité, hausse des revenus et de la demande, précédents historiques…", "Elle présente l’argument pessimiste : rapidité du changement, tâches cognitives touchées, inégalités, chômage structurel de transition, difficulté de reconversion…", "Elle mobilise au moins une notion : destruction créatrice (Schumpeter), chômage structurel, productivité, complémentarité ou substitution du travail…", "Elle évoque des politiques publiques possibles : formation continue, assurance chômage, fiscalité, orientation de la technologie (Acemoglu)…", "Elle se termine par une prise de position explicite (pour, contre ou à certaines conditions), justifiée par au moins un des arguments présentés."],
    corrige: P("<b>Les optimistes</b> rappellent que chaque grande innovation, de la machine à vapeur à l’informatique, a détruit des emplois mais en a créé davantage : c’est la <b>destruction créatrice</b> décrite par Schumpeter. L’IA peut augmenter la productivité, faire baisser les prix et donc augmenter le pouvoir d’achat et la demande d’autres biens et services. Elle peut aussi <b>compléter</b> le travail humain plutôt que le remplacer. Cette lecture s’inscrit dans la tradition néoclassique et schumpétérienne, pour laquelle les salaires et les emplois s’ajustent aux nouvelles techniques.", "<b>Les pessimistes</b>, dans la ligne de Ricardo, qui doutait en 1821 que les machines profitent à tous les travailleurs, et de Keynes, qui parlait en 1930 de « chômage technologique », soulignent que l’IA touche des tâches intellectuelles qu’on croyait protégées, et qu’elle se diffuse très vite. Même si de nouveaux emplois apparaissent, les personnes qui perdent le leur ne pourront pas toutes se reconvertir : on risque un <b>chômage structurel</b> de transition et une hausse des inégalités. Daron Acemoglu insiste sur le fait que l’effet dépend de l’orientation donnée à la technologie : automatiser ou aider les travailleurs.", "<b>Ce qui les oppose.</b> L’hypothèse qui sépare les deux camps est la capacité de l’économie à réabsorber les travailleurs déplacés : pour les premiers, les salaires s’ajustent, la demande s’élargit et la main-d’œuvre se reconvertit assez vite ; pour les seconds, la reconversion est lente et coûteuse, et la demande peut ne pas suivre.", "<b>Conclusion :</b> un chômage de masse durable n’est pas inévitable, mais la transition peut être douloureuse. Tout dépend des politiques d’accompagnement : formation continue, assurance chômage, fiscalité, et choix collectifs sur l’usage de l’IA.") },

  { id: "em3-deux-pays", theme: "emploi", niveau: 3, type: "document", notion: "hysterese",
    titre: "Allemagne et Espagne après la crise de 2008", competence: "Calculer des variations sur des données réelles et interpréter les indicateurs du chômage de longue durée.",
    enonce: P("Le tableau compare le chômage en Allemagne et en Espagne, de 2009 à 2013, après la crise financière de 2008.") +
      `<table><thead><tr><th></th><th>Allemagne 2009</th><th>Allemagne 2013</th><th>Espagne 2009</th><th>Espagne 2013</th></tr></thead><tbody>
      <tr><td>Taux de chômage (en % des actifs)</td><td>7,3</td><td>4,9</td><td>17,9</td><td>26,1</td></tr>
      <tr><td>Chômeurs depuis plus d’un an (en % des chômeurs)</td><td>48,8</td><td>48,1</td><td>23,8</td><td>49,7</td></tr>
      <tr><td>Chômeurs depuis plus d’un an (en % des actifs)</td><td>3,6</td><td>2,4</td><td>4,3</td><td>13,0</td></tr></tbody></table><p class="ex-source">Source : Eurostat, enquête sur les forces de travail (tableaux une_rt_a et une_ltu_a), personnes de 15 à 74 ans, données consultées le 26 novembre 2026.</p>` +
      P("Calculez d’abord la variation, entre 2009 et 2013, du chômage de longue durée en pourcentage des actifs dans chaque pays. Quelle interprétation est ensuite la plus cohérente avec ces données ?"),
    options: ["Le chômage de longue durée recule de 3,6 % à 2,4 % des actifs en Allemagne et monte de 4,3 % à 13,0 % en Espagne, comme l’hystérèse le prévoit.", "Le chômage de longue durée progresse dans les deux pays, puisque sa part dans le chômage total est semblable en 2013 (49,7 % et 48,1 %), ce qui indique une évolution commune.", "Le chômage de longue durée est aussi préoccupant en Allemagne qu’en Espagne, puisque la moitié des chômeurs allemands y reste plus d’un an.", "Ces données ne permettent pas de parler d’hystérèse, car elles ne renseignent pas sur la durée du chômage entre 2009 et 2013."], c: 0,
    pourquoi: [null, "En Allemagne, le chômage de longue durée recule de 1,2 point des actifs (de 3,6 % à 2,4 %). Une part semblable dans le chômage total ne dit rien sur son niveau, car le chômage allemand total a lui-même baissé.", "La part est semblable en 2013, mais pas le poids dans la population active : 2,4 % des actifs en Allemagne, 13,0 % en Espagne, soit plus de cinq fois plus. Une part ne mesure pas l’ampleur du problème.", "Le tableau donne bien la durée : la part des chômeurs depuis plus d’un an passe de 23,8 % à 49,7 % en Espagne. Ces données ne prouvent pas l’hystérèse, mais elles s’accordent avec elle."],
    explication: P("En Allemagne, le chômage de longue durée recule de <b>1,2 point</b> des actifs (2,4 − 3,6). En Espagne, il augmente de <b>8,7 points</b> (13,0 − 4,3) et sa part dans le chômage total double (de 23,8 % à 49,7 %). Une grande partie de la hausse du chômage s’est donc transformée en chômage de longue durée : la récession a laissé des « cicatrices », c’est l’<b>hystérèse</b>.", "Le piège est de comparer les parts. En 2013, elles sont presque égales (49,7 % et 48,1 %), alors que le chômage de longue durée touche 13,0 % des actifs en Espagne et 2,4 % en Allemagne. Quand le chômage total est faible, une part élevée de longue durée concerne peu de personnes.", "Ces données s’accordent avec l’hystérèse, mais ne la prouvent pas. L’Espagne a connu une seconde récession en 2011-2013 et d’autres différences entre les deux pays peuvent jouer, par exemple la structure de leurs économies et leurs institutions du marché du travail.") },
  { id: "em1-fait-valeur", theme: "emploi", niveau: 1, type: "vf", typeLib: "Constat ou jugement de valeur", etiquettes: ["Constat", "Jugement de valeur"],
    titre: "Constat, prévision ou jugement caché ?", competence: "Repérer les phrases d’apparence factuelle qui contiennent un jugement de valeur, et reconnaître qu’une prévision se vérifie.",
    enonce: P("Pour chaque phrase, dites s’il s’agit d’un <b>constat</b>, c’est-à-dire d’une affirmation que l’on peut vérifier avec des données, même si elle se révèle fausse (une prévision en fait partie, puisque l’avenir la confirmera ou non), ou d’un <b>jugement de valeur</b>, qui dit ce qui est bon, mauvais ou réussi. Certains jugements n’emploient aucun mot comme « devrait » ou « injuste »."),
    affirmations: [
      ["Un taux de chômage de 3 % montre que la politique du gouvernement a réussi.", false, "Le taux de chômage se mesure, mais « réussi » dépend des objectifs que l’on retient (emploi, salaires, inflation, qualité des emplois). La phrase a l’air d’un fait, elle cache un jugement de valeur."],
      ["Entre 2010 et 2019, le taux de chômage de la zone euro a été chaque année plus élevé que celui des États-Unis.", true, "On peut le vérifier dans les statistiques d’Eurostat et de l’OCDE. C’est un constat, qu’on l’approuve ou non."],
      ["Le chômage de longue durée est le signe d’un marché du travail qui fonctionne mal.", false, "Le nombre de chômeurs de longue durée se mesure, mais « fonctionne mal » suppose un critère de ce qu’un marché du travail doit accomplir. C’est un jugement de valeur sous une forme neutre."],
      ["Si la croissance reste inférieure à 1 % pendant deux ans, le taux de chômage augmentera.", true, "C’est une prévision : elle peut se révéler juste ou fausse, et l’on peut la tester avec des données, par exemple avec la loi d’Okun. Elle ne dit pas ce qui devrait arriver."]] },
  ]);
  /* =========================== COMPLÉMENTS : séries portées à douze exercices (novembre 2026) =========================== */
  X.add([
  /* ----- Niveau 1 ----- */
  { id: "em1-brut-net", theme: "emploi", niveau: 1, type: "calcul",
    titre: "Du salaire brut au salaire net", competence: "Calculer un salaire net à partir du salaire brut et des cotisations.",
    gen: () => ({ brut: rnd(42, 78) * 100, lpp: pick([180, 220, 260, 310, 350]) }),
    enonce: (p) => P(`Le salaire brut d’une employée est de <b>${fmt(p.brut)} francs</b> par mois. Son employeur en retient <b>6,4 %</b> pour les assurances sociales (AVS, AI, allocations pour perte de gain et assurance chômage, taux de 2026) et <b>${p.lpp} francs</b> pour sa caisse de pension.`, "Quel est son salaire net ? Les autres retenues, comme l’assurance accidents, sont laissées de côté."),
    champs: [{ label: "Salaire net", unite: "fr.", tol: 0.5 }],
    reponses: (p) => [Math.round((p.brut * 0.936 - p.lpp) * 100) / 100],
    indice: "Calculez d’abord la retenue de 6,4 % en francs, puis soustrayez les deux retenues du salaire brut.",
    correction: (p) => { const c = p.brut * 0.064; return P(`Retenue pour les assurances sociales : ${fmt(p.brut)} × 6,4 ÷ 100 = ${fmt(c)} francs.`, `Salaire net = ${fmt(p.brut)} − ${fmt(c)} − ${p.lpp} = <b>${fmt(p.brut - c - p.lpp)} francs</b>.`, "L’employeur verse de son côté des cotisations du même ordre. Le coût d’un poste dépasse donc nettement le salaire net que reçoit la personne, et l’écart finance les retraites, l’assurance invalidité et l’assurance chômage."); } },

  { id: "em1-graph-jeunes", theme: "emploi", niveau: 1, type: "graphique", notion: "demande-effective",
    titre: "Le chômage des jeunes et la conjoncture", competence: "Comparer deux séries sur un graphique en barres.",
    enonce: P("Le graphique compare, dans un pays, le taux de chômage de l’ensemble de la population active et celui des 15 à 24 ans. Une récession touche le pays en 2021.", "Que montre le graphique ?"),
    fig: () => X.barres({ cats: ["2019", "2020", "2021", "2022", "2023", "2024"], vals: [4, 4, 7, 6, 5, 4], vals2: [8, 8, 15, 12, 10, 8], noms: ["Ensemble", "15 à 24 ans"], ymax: 17, unite: "", dec: 0, aria: "Taux de chômage de l’ensemble de la population active et des 15 à 24 ans, de 2019 à 2024", caption: "Taux de chômage en %. Données inventées pour l’exercice." }),
    options: ["Le taux des jeunes vaut environ le double de la moyenne et augmente davantage en 2021.", "Le taux des jeunes suit celui de l’ensemble de la population avec une année de retard.", "Deux chômeurs sur trois sont des jeunes, puisque leur barre est deux fois plus haute.", "Après 2021, le taux des jeunes recule moins vite que la moyenne, en points de pourcentage."], c: 0,
    pourquoi: [null, "Les deux taux montent la même année, en 2021, et redescendent ensemble. Il n’y a pas de décalage.", "Un taux n’est pas une part. Le graphique dit que 15 % des jeunes actifs sont au chômage en 2021, pas que les jeunes forment la majorité des chômeurs. Ils sont bien moins nombreux que les autres actifs.", "Le taux des jeunes passe de 15 % à 8 %, soit 7 points de moins en trois ans. Celui de l’ensemble passe de 7 % à 4 %, soit 3 points de moins."],
    explication: P("Chaque année, le taux de chômage des jeunes est à peu près le <b>double</b> de la moyenne. En 2021, il augmente de 7 points (de 8 % à 15 %), contre 3 points pour l’ensemble.", "Les jeunes sont plus exposés à la conjoncture. Ils sont souvent les derniers embauchés, plus nombreux en contrats de durée limitée, et les entreprises en difficulté commencent par ne plus recruter.") },

  { id: "em1-doc-statut", theme: "emploi", niveau: 1, type: "document", notion: "taux-naturel",
    titre: "Qui est au chômage ?", competence: "Appliquer la définition du chômage à des situations individuelles.",
    enonce: P("Une enquête décrit la situation de cinq personnes pendant la semaine écoulée.") +
      `<table><thead><tr><th>Personne</th><th>Situation</th></tr></thead><tbody><tr><td>Aline, 34 ans</td><td>A travaillé 20 heures comme vendeuse.</td></tr><tr><td>Boris, 52 ans</td><td>Sans emploi, a envoyé trois candidatures ce mois-ci, peut commencer tout de suite.</td></tr><tr><td>Chloé, 19 ans</td><td>Étudiante, ne cherche pas d’emploi.</td></tr><tr><td>Dario, 45 ans</td><td>Sans emploi, aimerait travailler mais ne cherche plus depuis six mois.</td></tr><tr><td>Elsa, 67 ans</td><td>Retraitée.</td></tr></tbody></table><p class="ex-source">Situations inventées pour l’exercice.</p>` +
      P("Selon la définition du Bureau international du travail, qui est au chômage ?"),
    options: ["Boris seulement.", "Boris et Dario.", "Boris, Chloé et Dario.", "Aline, Boris et Dario."], c: 0,
    pourquoi: [null, "Dario n’a pas d’emploi et voudrait travailler, mais il ne cherche plus. Sans recherche active, il est classé parmi les personnes inactives. On parle de chômeur découragé.", "Chloé n’a pas d’emploi, mais elle n’en cherche pas. Elle est inactive, comme Elsa. Dario ne cherche plus et l’est aussi.", "Aline a travaillé pendant la semaine. Une heure rémunérée suffit pour être comptée parmi les personnes en emploi, même à temps partiel."],
    explication: P("Pour le Bureau international du travail, une personne est au chômage si elle remplit trois conditions à la fois. Elle est <b>sans emploi</b>, <b>disponible</b> rapidement et elle <b>cherche activement</b> un emploi.", "Seul <b>Boris</b> les remplit toutes. Aline est en emploi. Chloé, Dario et Elsa sont inactifs, parce qu’ils ne cherchent pas d’emploi.", "La population active réunit les personnes en emploi et les chômeurs, ici Aline et Boris. Le cas de Dario montre une limite de la mesure. Quand des chômeurs se découragent, le taux de chômage baisse sans que la situation s’améliore.") },

  /* ----- Niveau 2 ----- */
  { id: "em2-cout-salarie", theme: "emploi", niveau: 2, type: "calcul",
    titre: "Ce que coûte un poste à l’employeur", competence: "Calculer le coût total d’un salarié à partir des cotisations patronales.",
    gen: () => ({ brut: rnd(45, 90) * 100, lpp: pick([250, 300, 360, 420]), af: pick([1.5, 2, 2.5]) }),
    enonce: (p) => P(`Une entreprise verse à une salariée un salaire brut de <b>${fmt(p.brut)} francs</b> par mois. Elle paie en plus des cotisations patronales de <b>5,3 %</b> pour l’AVS, l’AI et les allocations pour perte de gain, de <b>1,1 %</b> pour l’assurance chômage (taux de 2026), de <b>${fmt(p.af)} %</b> pour les allocations familiales (taux d’exemple, il varie selon le canton) et de <b>${p.lpp} francs</b> pour la caisse de pension.`, "Calculez le total des cotisations patronales, le coût total du poste, puis ce que ce coût représente en plus du salaire brut. Arrondissez le pourcentage à une décimale."),
    champs: [{ label: "Cotisations patronales", unite: "fr.", tol: 0.5 }, { label: "Coût total du poste", unite: "fr.", tol: 0.5 }, { label: "Supplément par rapport au brut", unite: "%", tol: 0.1 }],
    reponses: (p) => { const c = p.brut * (6.4 + p.af) / 100 + p.lpp; return [Math.round(c * 100) / 100, Math.round((p.brut + c) * 100) / 100, Math.round(c / p.brut * 1000) / 10]; },
    indice: "Additionnez les trois taux et appliquez-les au salaire brut, puis ajoutez la cotisation à la caisse de pension, qui est donnée en francs.",
    correction: (p) => { const t = 6.4 + p.af, c = p.brut * t / 100 + p.lpp; return P(`Cotisations en pourcentage : (5,3 + 1,1 + ${fmt(p.af)}) % = ${fmt(t)} % de ${fmt(p.brut)} francs, soit ${fmt(p.brut * t / 100)} francs.`, `Cotisations patronales = ${fmt(p.brut * t / 100)} + ${p.lpp} = <b>${fmt(c)} francs</b>.`, `Coût total du poste = ${fmt(p.brut)} + ${fmt(c)} = <b>${fmt(p.brut + c)} francs</b>.`, `Supplément = ${fmt(c)} ÷ ${fmt(p.brut)} × 100 ≈ <b>${fmt(c / p.brut * 100, 1)} %</b>.`, "Pour décider d’une embauche, l’entreprise compare ce coût total, et non le salaire brut, à ce que le poste lui rapporte. Savoir qui supporte réellement ces cotisations est une autre question. Si l’offre de travail réagit peu au salaire, elles se reportent en grande partie sur les salariés, sous la forme de salaires bruts plus bas."); } },

  { id: "em2-graph-beveridge", theme: "emploi", niveau: 2, type: "graphique", notion: "taux-naturel",
    titre: "La courbe de Beveridge", competence: "Distinguer sur un graphique un choc conjoncturel d’une dégradation de l’appariement.",
    enonce: P("La courbe de Beveridge relie le taux de chômage et le taux de postes vacants. Le graphique montre deux courbes et trois situations A, B et C.", "Quel passage signale que les chômeurs et les postes vacants se correspondent moins bien qu’avant ?"),
    fig: () => X.graphe({ xmax: 9.4, ymax: 5.4, ylab: "Postes vacants (%)", xlab: "Taux de chômage (%)", aria: "Deux courbes de Beveridge décroissantes et trois points A, B et C",
      gx: [[2, "2"], [6, "6"]], gy: [[1, "1"], [3, "3"]],
      lignes: [{ f: (u) => 6 / u, de: 1.2, a: 9, col: "d", lab: "courbe 1", at: [9, 0.67], dy: 22, anc: "end" }, { f: (u) => 10 / u, de: 2, a: 9, col: "o", dash: true, lab: "courbe 2", at: [9, 1.11], dy: -12, anc: "end" }],
      points: [{ x: 2, y: 3, lab: "A", dx: 10, dy: -6 }, { x: 6, y: 1, lab: "B", dx: -6, dy: 22, anc: "end" }, { x: 6, y: 10 / 6, lab: "C", col: "o", dx: 8, dy: -10 }],
      caption: "Chaque courbe correspond à une qualité donnée de l’appariement entre chômeurs et postes vacants." }),
    options: ["Le passage de B à C, où il y a davantage de postes vacants pour un même taux de chômage.", "Le passage de A à B, où le chômage augmente pendant que les postes vacants diminuent.", "Le passage de B à A, où le chômage diminue pendant que les postes vacants augmentent.", "Aucun des trois, car chômage et postes vacants varient en sens inverse sur les deux courbes."], c: 0,
    pourquoi: [null, "De A à B, on glisse le long de la même courbe. Les entreprises ont moins de postes à pourvoir et le chômage monte. C’est l’effet d’une récession, pas d’un moins bon appariement.", "De B à A, on glisse le long de la courbe 1 dans l’autre sens. C’est une reprise, où les embauches augmentent et le chômage recule.", "Sur chaque courbe, les deux grandeurs varient bien en sens inverse. Mais le passage d’une courbe à l’autre est un autre phénomène, et c’est lui qui renseigne sur l’appariement."],
    explication: P("Un déplacement <b>le long</b> de la courbe reflète la conjoncture. En récession, les postes vacants se raréfient et le chômage monte (de A vers B).", "Un déplacement <b>de la courbe</b> vers l’extérieur signale un problème d’appariement. En C, il y a plus de postes vacants qu’en B pour le même chômage de 6 %. Les postes existent, mais ils ne correspondent pas aux chômeurs, par la qualification, le métier ou la région.", "La distinction guide la politique. Contre un chômage conjoncturel, on soutient la demande. Contre un problème d’appariement, la relance ne suffit pas, et il faut plutôt former, informer et faciliter la mobilité.") },

  { id: "em2-doc-csu", theme: "emploi", niveau: 2, type: "document",
    titre: "Salaires, productivité et compétitivité", competence: "Comparer des coûts salariaux unitaires à partir de salaires et de productivités.",
    enonce: P("Le tableau donne, pour trois pays, la variation sur un an du salaire horaire et de la productivité horaire du travail.") +
      `<table><thead><tr><th>Pays</th><th>Salaire horaire</th><th>Productivité horaire</th></tr></thead><tbody><tr><td>A</td><td>+3 %</td><td>+1 %</td></tr><tr><td>B</td><td>+5 %</td><td>+5 %</td></tr><tr><td>C</td><td>+1 %</td><td>−1 %</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Dans quel pays le coût salarial par unité produite évolue-t-il le plus favorablement pour les entreprises ?"),
    options: ["Dans le pays B, où il reste stable malgré la plus forte hausse des salaires.", "Dans le pays C, où les salaires augmentent le moins.", "Dans le pays A, où les salaires augmentent moins vite que dans le pays B.", "Dans les pays A et B à égalité, puisque la productivité progresse dans les deux."], c: 0,
    pourquoi: [null, "Les salaires n’y augmentent que de 1 %, mais chaque heure produit 1 % de moins. Le coût par unité produite augmente d’environ 2 %.", "Dans le pays A, les salaires augmentent de 3 % pour une productivité en hausse de 1 % seulement. Le coût par unité produite augmente d’environ 2 %, contre 0 % dans le pays B.", "La productivité progresse dans les deux pays, mais elle ne compense pas la même part de la hausse des salaires. Elle en compense la totalité dans le pays B, un tiers seulement dans le pays A."],
    explication: P("Le <b>coût salarial unitaire</b> est le salaire horaire divisé par la productivité horaire. Sa variation vaut à peu près celle du salaire moins celle de la productivité.", "Pays A : 3 − 1 = <b>+2 %</b>. Pays B : 5 − 5 = <b>0 %</b>. Pays C : 1 − (−1) = <b>+2 %</b>.", "Des salaires qui augmentent vite ne dégradent donc pas la compétitivité s’ils suivent la productivité. À l’inverse, une modération des salaires ne protège pas un pays dont la productivité recule.") },

  { id: "em2-rht", theme: "emploi", niveau: 2, type: "calcul", notion: "demande-effective",
    titre: "Une indemnité de chômage partiel", competence: "Calculer le revenu d’un salarié dont l’horaire est réduit.",
    gen: () => ({ sal: rnd(45, 80) * 100, red: pick([20, 30, 40, 50, 60]) }),
    enonce: (p) => P(`Face à une chute des commandes, une entreprise réduit de <b>${p.red} %</b> l’horaire d’un salarié qui gagne <b>${fmt(p.sal)} francs</b> par mois. Son salaire baisse dans la même proportion. L’assurance chômage lui verse une indemnité égale à <b>80 %</b> de la perte de salaire. Ce dispositif s’appelle en Suisse réduction de l’horaire de travail, et chômage partiel dans d’autres pays.`, "Calculez l’indemnité, le revenu total du salarié pendant cette période, puis ce que ce revenu représente par rapport à son salaire habituel (en %, une décimale)."),
    champs: [{ label: "Indemnité", unite: "fr.", tol: 0.5 }, { label: "Revenu total", unite: "fr.", tol: 0.5 }, { label: "Part du salaire habituel", unite: "%", tol: 0.1 }],
    reponses: (p) => { const perte = p.sal * p.red / 100; return [0.8 * perte, p.sal - 0.2 * perte, 100 - 0.2 * p.red]; },
    indice: "Calculez d’abord la perte de salaire en francs. L’indemnité en couvre 80 %, le salarié garde donc 20 % de cette perte à sa charge.",
    correction: (p) => { const perte = p.sal * p.red / 100; return P(`Perte de salaire : ${fmt(p.sal)} × ${p.red} ÷ 100 = ${fmt(perte)} francs. L’entreprise verse encore ${fmt(p.sal - perte)} francs.`, `Indemnité = 80 % × ${fmt(perte)} = <b>${fmt(0.8 * perte)} francs</b>.`, `Revenu total = ${fmt(p.sal - perte)} + ${fmt(0.8 * perte)} = <b>${fmt(p.sal - 0.2 * perte)} francs</b>.`, `Part du salaire habituel = ${fmt(p.sal - 0.2 * perte)} ÷ ${fmt(p.sal)} × 100 = <b>${fmt(100 - 0.2 * p.red, 1)} %</b>.`, "Le salarié garde son emploi et l’essentiel de son revenu, l’entreprise garde un personnel formé. Le dispositif amortit une baisse passagère de la demande. Il a une limite. S’il dure, il peut maintenir des emplois dans des entreprises qui ne retrouveront pas leurs commandes."); } },

  /* ----- Niveau 3 ----- */
  { id: "em3-ws-ps", theme: "emploi", niveau: 3, type: "calcul", notion: "taux-naturel",
    titre: "Le chômage d’équilibre entre salaires et prix", competence: "Résoudre un modèle de formation des salaires et des prix et faire une statique comparative.",
    gen: () => { const mu = pick([10, 20, 25]); return { b: pick([2, 2.5, 4]), mu, mu2: mu === 10 ? 5 : 10 }; },
    enonce: (p) => P(`Dans une économie où un travailleur produit une unité de bien, les salaires négociés suivent <b>W ÷ P = 1 − ${fmt(p.b)}·u</b>, où u est le taux de chômage écrit en fraction. Plus le chômage est élevé, moins les salariés obtiennent. Les entreprises fixent leurs prix en ajoutant une marge de <b>${p.mu} %</b> au coût salarial, soit P = ${fmt(1 + p.mu / 100)} × W.`, `Calculez le salaire réel que permettent les prix (trois décimales), le taux de chômage d’équilibre, puis ce taux si la concurrence ramène la marge à <b>${p.mu2} %</b>. Arrondissez les taux à une décimale.`),
    champs: [{ label: "Salaire réel W ÷ P", unite: "", tol: 0.002 }, { label: "Chômage d’équilibre", unite: "%", tol: 0.1 }, { label: `Chômage avec la nouvelle marge`, unite: "%", tol: 0.1 }],
    reponses: (p) => { const u = (m) => Math.round((1 - 1 / (1 + m / 100)) / p.b * 1000) / 10; return [Math.round(1000 / (1 + p.mu / 100)) / 1000, u(p.mu), u(p.mu2)]; },
    indice: "L’équation des prix donne directement W ÷ P. Le chômage d’équilibre est celui pour lequel les salaires négociés sont égaux à ce salaire réel.",
    correction: (p) => { const w = 1 / (1 + p.mu / 100), u = (1 - w) / p.b * 100, w2 = 1 / (1 + p.mu2 / 100), u2 = (1 - w2) / p.b * 100; return P(`Les prix fixent le salaire réel : W ÷ P = 1 ÷ ${fmt(1 + p.mu / 100)} ≈ <b>${fmt(w, 3)}</b>.`, `Équilibre : 1 − ${fmt(p.b)}·u = ${fmt(w, 3)}, donc u = (1 − ${fmt(w, 3)}) ÷ ${fmt(p.b)} ≈ ${fmt(u / 100, 4)}, soit <b>${fmt(u, 1)} %</b>.`, `Avec une marge de ${p.mu2} %, W ÷ P = ${fmt(w2, 3)} et u = (1 − ${fmt(w2, 3)}) ÷ ${fmt(p.b)}, soit <b>${fmt(u2, 1)} %</b>.`, "Le chômage d’équilibre est celui qui rend compatibles ce que les salariés obtiennent et ce que les entreprises concèdent. Des marges plus faibles laissent un salaire réel plus élevé, et il faut moins de chômage pour que les deux côtés s’accordent.", "Ce modèle, dû à Richard Layard, Stephen Nickell et Richard Jackman, donne un contenu au taux de chômage naturel de Friedman. Il explique le chômage par les institutions du marché du travail et par la concurrence sur le marché des biens. Les tenants de l’hystérèse lui reprochent de traiter cet équilibre comme indépendant de la demande. Michał Kalecki y aurait reconnu son idée que le chômage sert à discipliner les salaires."); } },

  { id: "em3-did", theme: "emploi", niveau: 3, type: "calcul", notion: "concurrence-imparfaite",
    titre: "Mesurer l’effet d’un salaire minimum", competence: "Calculer une estimation par doubles différences et la comparer à une estimation naïve.",
    gen: () => { const t0 = rnd(180, 240) / 10, c0 = rnd(190, 250) / 10, dt = pick([-0.8, -0.4, 0.3, 0.6]), dc = pick([-2.2, -1.5, -1]); return { t0, c0, t1: Math.round((t0 + dt) * 10) / 10, c1: Math.round((c0 + dc) * 10) / 10 }; },
    enonce: (p) => P("Une région relève son salaire minimum. Un institut mesure l’emploi moyen par restaurant, en équivalents plein temps, dans cette région et dans une région voisine où rien ne change.") +
      `<table><thead><tr><th>Emploi moyen par restaurant</th><th>Avant</th><th>Après</th></tr></thead><tbody><tr><td>Région qui relève le salaire minimum</td><td>${fmt(p.t0, 1)}</td><td>${fmt(p.t1, 1)}</td></tr><tr><td>Région voisine</td><td>${fmt(p.c0, 1)}</td><td>${fmt(p.c1, 1)}</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice, sur le modèle de l’étude de David Card et d’Alan Krueger (1994).</p>` +
      P("Calculez l’effet du salaire minimum sur l’emploi par une simple comparaison avant et après dans la première région, puis par la méthode des doubles différences. Indiquez un signe moins pour une baisse."),
    champs: [{ label: "Comparaison avant et après", unite: "emplois", tol: 0.05 }, { label: "Doubles différences", unite: "emplois", tol: 0.05 }],
    reponses: (p) => [Math.round((p.t1 - p.t0) * 10) / 10, Math.round((p.t1 - p.t0 - (p.c1 - p.c0)) * 10) / 10],
    indice: "La région voisine indique ce qui se serait passé sans la hausse. Retranchez sa variation de celle de la première région.",
    correction: (p) => { const a = Math.round((p.t1 - p.t0) * 10) / 10, c = Math.round((p.c1 - p.c0) * 10) / 10, d = Math.round((a - c) * 10) / 10; return P(`Avant et après : ${fmt(p.t1, 1)} − ${fmt(p.t0, 1)} = <b>${fmt(a, 1)}</b> emploi par restaurant.`, `Variation dans la région voisine : ${fmt(p.c1, 1)} − ${fmt(p.c0, 1)} = ${fmt(c, 1)}. Elle mesure l’effet de la conjoncture commune aux deux régions.`, `Doubles différences : ${fmt(a, 1)} − (${fmt(c, 1)}) = <b>${fmt(d, 1)}</b> emploi par restaurant.`, "La simple comparaison avant et après attribue au salaire minimum tout ce qui a changé entre les deux dates. La seconde méthode retire l’évolution commune. Ici l’emploi a mieux résisté là où le salaire minimum a augmenté.", "Le résultat repose sur une hypothèse, celle des tendances parallèles. Sans la hausse, l’emploi aurait évolué de la même façon dans les deux régions. Card et Krueger ont conclu à l’absence d’effet négatif, ce qui s’accorde avec un pouvoir de marché des employeurs (monopsone). David Neumark et William Wascher ont contesté leurs données et trouvé des pertes d’emplois, conformes au modèle concurrentiel."); } },

  { id: "em3-graph-monopsone", theme: "emploi", niveau: 3, type: "graphique", notion: "concurrence-imparfaite",
    titre: "Le salaire minimum face à un monopsone", competence: "Lire le graphique d’un monopsone et prévoir l’effet d’un salaire minimum.",
    enonce: P("Un hôpital est le seul employeur d’infirmiers de sa région. Le graphique montre l’offre de travail, le coût marginal du travail pour l’hôpital et la productivité marginale du travail. Sans intervention, l’hôpital emploie 10 personnes à 20 francs de l’heure (point M). Un salaire minimum de 25 francs est introduit.", "Quelle lecture est correcte ?"),
    fig: () => X.graphe({ xmax: 31, ymax: 46, ylab: "Salaire horaire (fr.)", xlab: "Emploi", aria: "Monopsone : offre de travail, coût marginal du travail et productivité marginale",
      gx: [[10, "10"], [15, "15"]], gy: [[20, "20"], [25, "25"], [30, "30"]], reperes: [[10, 30], [15, 25]],
      lignes: [{ pts: [[0, 10], [27, 37]], col: "o", lab: "offre", at: [27, 37], dx: 4, dy: 5 }, { pts: [[0, 10], [16, 42]], col: "r", lab: "coût marginal", at: [16, 42], dx: 6, dy: 4 }, { pts: [[0, 40], [29, 11]], col: "d", lab: "productivité", at: [29, 11], dy: 22, anc: "end" }],
      points: [{ x: 10, y: 20, lab: "M", dx: 8, dy: 16 }, { x: 15, y: 25, lab: "C", dx: 18, dy: 5 }, { x: 10, y: 30, col: "r" }],
      caption: "Offre w = 10 + L, coût marginal du travail 10 + 2L, productivité marginale 40 − L." }),
    options: ["L’emploi passe de 10 à 15, car l’hôpital n’a plus à relever le salaire de tous pour embaucher.", "L’emploi recule, car le salaire dépasse désormais la productivité de la dernière personne embauchée.", "L’emploi reste à 10 et seul le salaire change, puisque l’hôpital est l’unique employeur.", "L’emploi passe de 10 à 15, et un salaire minimum de 35 francs l’augmenterait encore davantage."], c: 0,
    pourquoi: [null, "En M, la dixième personne rapporte 30 francs et n’en reçoit que 20. À 25 francs, il reste rentable d’embaucher jusqu’à la quinzième, dont la productivité est de 25 francs.", "L’hôpital choisit l’emploi. À 25 francs, chaque embauche lui coûte 25 francs et rapporte davantage jusqu’à la quinzième personne. Il a donc intérêt à embaucher.", "À 35 francs, l’hôpital n’emploierait que les personnes dont la productivité atteint 35 francs, soit 5. Au-delà du salaire concurrentiel de 25 francs, un salaire minimum réduit l’emploi."],
    explication: P("Sans intervention, l’hôpital embauche tant que la productivité marginale dépasse le <b>coût marginal du travail</b>, qui est supérieur au salaire. Pour attirer une personne de plus, il doit en effet augmenter le salaire de toutes. L’égalité 40 − L = 10 + 2L donne L = 10, payé 10 + 10 = 20 francs.", "Avec un salaire minimum de 25 francs, le coût d’une embauche devient constant à 25 francs jusqu’à 15 personnes. L’hôpital embauche jusqu’à ce que 40 − L = 25, soit <b>L = 15</b>. C’est le résultat de la concurrence (point C).", "Le salaire minimum augmente donc ici le salaire et l’emploi, ce que l’analyse du monopsone par Joan Robinson (1933) permet de montrer. Le résultat ne vaut qu’entre 20 et 25 francs dans cet exemple. La question de savoir si les marchés du travail réels ressemblent à ce modèle ou au modèle concurrentiel reste discutée.") },

  { id: "em3-red-theories", theme: "emploi", niveau: 3, type: "redaction", notion: "hysterese",
    titre: "Pourquoi le chômage persiste-t-il ?", competence: "Comparer plusieurs théories du chômage et ce qu’elles impliquent pour la politique économique.",
    enonce: P("Après la crise de 2008, le chômage est resté élevé pendant près de dix ans dans plusieurs pays d’Europe du Sud, alors qu’il est resté bas ou vite redescendu en Allemagne et en Suisse. Les économistes expliquent un chômage durable de plusieurs façons.", "<b>Consigne :</b> comparez au moins trois explications du chômage durable en les rattachant à leurs auteurs (taux naturel de Friedman et Phelps, insuffisance de la demande chez Keynes, hystérèse chez Blanchard et Summers, rôle disciplinaire du chômage chez Marx et Kalecki, appariement chez Diamond, Mortensen et Pissarides). Décrivez le mécanisme de chacune, montrez sur quelle hypothèse elles s’opposent, dites quelle politique chacune recommande, puis prenez position. Longueur attendue, 20 à 30 lignes."),
    criteres: ["La réponse présente au moins trois explications et nomme leurs auteurs.", "Elle décrit le mécanisme de chacune (institutions et incitations, demande insuffisante, traces laissées par une récession, rapport de force, délais de rencontre).", "Elle identifie une hypothèse qui les sépare, par exemple le fait que le chômage d’équilibre dépende ou non de la demande passée.", "Elle associe à chaque explication une politique (réformes du marché du travail, relance, formation et accompagnement, protection des salariés).", "Elle se termine par une prise de position explicite, justifiée par au moins un des arguments présentés."],
    corrige: P("<b>Taux naturel.</b> Pour Milton Friedman et Edmund Phelps, il existe un taux de chômage d’équilibre déterminé par les institutions, comme l’assurance chômage, le salaire minimum ou la protection de l’emploi. Une relance ne le fait baisser que temporairement, au prix d’une inflation croissante. Pour le réduire, il faut réformer le marché du travail.", "<b>Demande insuffisante.</b> Pour Keynes, l’emploi dépend de la demande attendue par les entreprises. Une économie peut rester durablement en sous-emploi, et la baisse des salaires aggrave le mal en réduisant la demande. Le remède est la relance budgétaire et monétaire. Les politiques d’austérité menées en Europe du Sud après 2010 illustrent, pour les keynésiens, l’effet inverse.", "<b>Hystérèse.</b> Olivier Blanchard et Lawrence Summers montrent qu’une récession laisse des traces. Les chômeurs de longue durée perdent leurs compétences et pèsent peu sur les salaires. Le chômage d’équilibre monte après une longue crise. La distinction entre conjoncture et structure s’efface, et une relance précoce évite un chômage qui deviendrait durable.", "<b>Rapport de force.</b> Pour Marx, une « armée de réserve » de chômeurs contient les salaires. Michał Kalecki ajoute en 1943 que le plein emploi durable affaiblit la discipline dans les entreprises, ce qui explique les résistances politiques qu’il rencontre.", "<b>Opposition centrale.</b> Les deux premières lectures traitent séparément l’équilibre de long terme et la conjoncture. L’hystérèse les relie. Si le chômage d’équilibre dépend de la demande passée, laisser durer une récession a un coût permanent.", "<b>Prise de position possible.</b> L’écart entre pays après 2008 tient aux deux. Le chômage partiel et l’apprentissage ont protégé l’emploi en Allemagne et en Suisse, ce qui donne raison aux explications par les institutions. Mais la durée du chômage en Europe du Sud, où la demande a été comprimée pendant des années, s’accorde mieux avec l’hystérèse qu’avec un taux naturel fixe.") },
]);
  /* =========================== FIN DES COMPLÉMENTS =========================== */
})();
